            TPBuffer[i] = high[i] + Tppoints * _Point;
            SLBuffer[i] = high[i] - Slpoints * _Point;
        }

        // Sinal de Venda (Vale de preço/Mínima) - Representa um possível ponto de entrada
        if (low[i] == lowest && low[i] < low[i-1]) // Se a barra atual atingiu a mínima do período e é menor que a anterior
        {
            SellEntryBuffer[i] = low[i];
            // Define TP e SL a partir do ponto de entrada
            TPBuffer[i] = low[i] - Tppoints * _Point;
            SLBuffer[i] = low[i] + Slpoints * _Point;
        }
    }

    return (rates_total);
}

