//+------------------------------------------------------------------+
double findHigh(const double &high_array[], int start_index, int bars_to_check)
{
    double highest = high_array[start_index];
    for (int i = 1; i < bars_to_check; i++)
    {
        double current_high = high_array[start_index + i];
        if (current_high > highest) 
        {
            highest = current_high;
        }
    }
    return highest;
}

